package com.campus.expense;
import java.time.*;import java.time.format.*;import java.util.*;
public class ConsoleHelper {private final Scanner s;public ConsoleHelper(Scanner s){this.s=s;}public String text(String p){System.out.print(p);return s.nextLine();}public int integer(String p){while(true)try{return Integer.parseInt(text(p).trim());}catch(NumberFormatException e){System.out.println("Enter a valid integer.");}}public double amount(String p){while(true)try{return Double.parseDouble(text(p).trim());}catch(NumberFormatException e){System.out.println("Enter a valid number.");}}public Category category(){while(true)try{return Category.valueOf(text("Category (FOOD/TRAVEL/EDUCATION/SHOPPING/HEALTH/ENTERTAINMENT/OTHER): ").trim().toUpperCase());}catch(IllegalArgumentException e){System.out.println("Invalid category.");}}public LocalDate date(){while(true)try{return LocalDate.parse(text("Date (YYYY-MM-DD): ").trim());}catch(DateTimeParseException e){System.out.println("Use YYYY-MM-DD.");}}public YearMonth month(){while(true)try{return YearMonth.parse(text("Month (YYYY-MM): ").trim());}catch(DateTimeParseException e){System.out.println("Use YYYY-MM.");}}}
